package agent

import (
	"errors"
	"fmt"
	"sort"
	"strings"
	"text/template"
	"text/template/parse"
	"time"
	"unicode/utf8"

	"github.com/EdouardRichard/EzTest/backend/internal/platform"
)

// MaxPromptRunes is the frozen profile prompt length limit (spec §8.4).
const MaxPromptRunes = 32768

// Prompt revision sources of the frozen contract.
const (
	PromptSourceSeed  = "seed"
	PromptSourceAdmin = "admin"
	PromptSourceReset = "reset"
)

// PromptVariableSourceRuntime is the only allowed variable source: values are
// generated by the server at run time (spec §8.4).
const PromptVariableSourceRuntime = "runtime"

// Prompt variable stability classes of the cache-stable system prompt (Task 81).
// Stable variables are constant for a profile/version/stage and may appear in
// the system prompt. Run variables change per run or per work item (time, task
// goal, case ids, ...); they must be carried by the task/user message instead,
// because the system prompt is the provider cache-stable prefix.
const (
	PromptVariableStabilityStable = "stable"
	PromptVariableStabilityRun    = "run"
)

// ErrPromptVersionConflict reports an expected_version mismatch. The
// application maps it to 409 state_conflict.
var ErrPromptVersionConflict = errors.New("agent: prompt version conflict")

// PromptVariable is one controllable prompt template variable. The catalog is
// code-defined; values are never supplied by a client at run time.
type PromptVariable struct {
	Name        string `json:"name"`
	Description string `json:"description"`
	Example     string `json:"example"`
	Source      string `json:"source"`
	// Stability is PromptVariableStabilityStable or
	// PromptVariableStabilityRun. Anything other than an explicit "stable"
	// classification is treated as per-run and rejected from the system prompt,
	// so a forgotten classification fails closed instead of silently
	// invalidating the cache prefix. It is internal catalog metadata and is not
	// part of the frozen admin variables schema.
	Stability string `json:"-"`
}

// PromptRevision is one append-only agent_profile_prompt_revision row.
type PromptRevision struct {
	ID           int64
	ProfileKey   string
	Version      int
	SystemPrompt string
	Note         string
	Source       string
	ActorID      *int64
	CreatedAt    time.Time
}

// Validate checks the revision identity, body and source.
func (r PromptRevision) Validate() error {
	if strings.TrimSpace(r.ProfileKey) == "" {
		return platform.Invalid("profile_key", "must not be empty")
	}
	if r.Version <= 0 {
		return platform.Invalid("version", "must be a positive integer")
	}
	if strings.TrimSpace(r.SystemPrompt) == "" {
		return platform.Invalid("system_prompt", "must not be empty")
	}
	if err := ValidatePromptSource(r.Source); err != nil {
		return err
	}
	return nil
}

// PromptVersionInfo is the current revision metadata of one profile.
type PromptVersionInfo struct {
	Version   int
	CreatedAt time.Time
}

// PromptWrite is one checked prompt append request. ExpectedVersion is the
// optional optimistic lock, and NoOpOnSame skips the append when the submitted
// body equals the current agent_profile.system_prompt (PUT no-op semantics).
type PromptWrite struct {
	ProfileKey      string
	SystemPrompt    string
	Note            string
	Source          string
	ActorID         *int64
	ExpectedVersion *int
	NoOpOnSame      bool
}

// Validate checks the write identity, source and optimistic lock.
func (w PromptWrite) Validate() error {
	if strings.TrimSpace(w.ProfileKey) == "" {
		return platform.Invalid("key", "must not be empty")
	}
	if strings.TrimSpace(w.SystemPrompt) == "" {
		return platform.Invalid("system_prompt", "must not be empty")
	}
	if err := ValidatePromptSource(w.Source); err != nil {
		return err
	}
	if w.ExpectedVersion != nil && *w.ExpectedVersion <= 0 {
		return platform.Invalid("expected_version", "must be a positive integer")
	}
	return nil
}

// PromptWriteResult reports the current version after a prompt write and
// whether a new revision was appended.
type PromptWriteResult struct {
	Version int
	Changed bool
}

// ProfileUpdate describes one partial profile PATCH. SetModel distinguishes
// "field absent" (false) from "clear to default" (true with Model nil or empty).
type ProfileUpdate struct {
	SetModel     bool
	Model        *string
	Budgets      *ProfileBudgets
	AllowedTools *[]string
}

// Empty reports whether no writable field is present.
func (u ProfileUpdate) Empty() bool {
	return !u.SetModel && u.Budgets == nil && u.AllowedTools == nil
}

// ValidatePromptSource checks the frozen revision source enum.
func ValidatePromptSource(source string) error {
	switch source {
	case PromptSourceSeed, PromptSourceAdmin, PromptSourceReset:
		return nil
	default:
		return platform.Invalid("source", "must be one of seed, admin, reset")
	}
}

// ValidatePrompt validates a full profile prompt body: non-empty, bounded,
// keeps the [profile:<key>] marker and is a template restricted to the
// code-defined variable catalog (spec §8.4). Because this body is rendered into
// the cache-stable system prefix, per-run variables are rejected (Task 81).
func ValidatePrompt(key, prompt string, catalog []PromptVariable) error {
	if strings.TrimSpace(prompt) == "" {
		return platform.Invalid("system_prompt", "must not be empty")
	}
	if utf8.RuneCountInString(prompt) > MaxPromptRunes {
		return platform.Invalid("system_prompt", "must be at most 32768 characters")
	}
	if !strings.Contains(prompt, "[profile:"+key+"]") {
		return promptError("missing_profile_marker", "must keep the [profile:"+key+"] marker")
	}
	return ValidateSystemPromptTemplate(prompt, catalog)
}

// ValidateSystemPromptTemplate validates a system prompt body against the
// catalog and rejects every per-run variable: the system prompt is the provider
// cache-stable prefix, so a per-run value would change the prefix on every run
// (Task 81). The rejection is a typed, actionable invalid_argument
// (reason=unstable_variable, variables=[...]) telling the administrator to move
// the value to the task/user message.
func ValidateSystemPromptTemplate(prompt string, catalog []PromptVariable) error {
	stability := make(map[string]string, len(catalog))
	for _, variable := range catalog {
		stability[variable.Name] = variable.Stability
	}
	unstable := make([]string, 0, 2)
	seen := make(map[string]struct{}, 2)
	err := validatePromptTemplate(prompt, catalog, func(name string) {
		if stability[name] == PromptVariableStabilityStable {
			return
		}
		if _, duplicate := seen[name]; duplicate {
			return
		}
		seen[name] = struct{}{}
		unstable = append(unstable, name)
	})
	if err != nil {
		return err
	}
	if len(unstable) == 0 {
		return nil
	}
	sort.Strings(unstable)
	qualified := make([]string, len(unstable))
	for index, name := range unstable {
		qualified[index] = "." + name
	}
	rejection := promptError("unstable_variable", fmt.Sprintf(
		"system prompt is the cache-stable prefix; per-run variable(s) %s must be moved to the task/user message (keep only stable variables here)",
		strings.Join(qualified, ", ")))
	rejection.Details["variables"] = unstable
	return rejection
}

// ValidatePromptTemplate checks the Go text/template syntax and requires every
// dynamic value to be a direct top-level {{.Variable}} of the catalog. No
// function calls, pipelines or nested field access are allowed. It does not
// judge variable stability; system prompt bodies must go through
// ValidateSystemPromptTemplate.
func ValidatePromptTemplate(prompt string, catalog []PromptVariable) error {
	return validatePromptTemplate(prompt, catalog, nil)
}

// validatePromptTemplate is the shared parser/walker of the template
// validators. onVariable, when non-nil, is called once per valid catalog
// variable reference.
func validatePromptTemplate(prompt string, catalog []PromptVariable, onVariable func(name string)) error {
	if strings.TrimSpace(prompt) == "" {
		return platform.Invalid("system_prompt", "must not be empty")
	}
	parsed, err := template.New("system_prompt").Option("missingkey=error").Parse(prompt)
	if err != nil {
		return promptError("invalid_template", "invalid template syntax: "+err.Error())
	}
	if parsed.Tree == nil || parsed.Tree.Root == nil {
		return promptError("invalid_template", "invalid template")
	}
	allowed := make(map[string]struct{}, len(catalog))
	for _, variable := range catalog {
		allowed[variable.Name] = struct{}{}
	}
	return validatePromptNodes(parsed.Tree.Root.Nodes, allowed, onVariable)
}

func validatePromptNodes(nodes []parse.Node, allowed map[string]struct{}, onVariable func(name string)) error {
	for _, node := range nodes {
		switch typed := node.(type) {
		case *parse.TextNode:
			continue
		case *parse.ActionNode:
			if err := validatePromptPipe(typed.Pipe, allowed, onVariable); err != nil {
				return err
			}
		case *parse.IfNode:
			if err := validatePromptPipe(typed.Pipe, allowed, onVariable); err != nil {
				return err
			}
			if err := validatePromptBranch(typed.List, typed.ElseList, allowed, onVariable); err != nil {
				return err
			}
		case *parse.RangeNode:
			if err := validatePromptPipe(typed.Pipe, allowed, onVariable); err != nil {
				return err
			}
			if err := validatePromptBranch(typed.List, typed.ElseList, allowed, onVariable); err != nil {
				return err
			}
		case *parse.WithNode:
			if err := validatePromptPipe(typed.Pipe, allowed, onVariable); err != nil {
				return err
			}
			if err := validatePromptBranch(typed.List, typed.ElseList, allowed, onVariable); err != nil {
				return err
			}
		default:
			return promptError("invalid_template", "template supports only text, variables and if/range/with blocks")
		}
	}
	return nil
}

func validatePromptBranch(list, elseList *parse.ListNode, allowed map[string]struct{}, onVariable func(name string)) error {
	if list != nil {
		if err := validatePromptNodes(list.Nodes, allowed, onVariable); err != nil {
			return err
		}
	}
	if elseList != nil {
		if err := validatePromptNodes(elseList.Nodes, allowed, onVariable); err != nil {
			return err
		}
	}
	return nil
}

func validatePromptPipe(pipe *parse.PipeNode, allowed map[string]struct{}, onVariable func(name string)) error {
	if pipe == nil || len(pipe.Decl) > 0 || len(pipe.Cmds) != 1 {
		return promptError("invalid_template", "template supports only direct {{.Variable}} substitutions")
	}
	command := pipe.Cmds[0]
	if command == nil || len(command.Args) != 1 {
		return promptError("invalid_template", "template supports only direct {{.Variable}} substitutions")
	}
	field, ok := command.Args[0].(*parse.FieldNode)
	if !ok {
		return promptError("invalid_template", "template supports only direct {{.Variable}} substitutions")
	}
	if len(field.Ident) != 1 {
		return promptError("unknown_variable", "unknown template variable ."+strings.Join(field.Ident, "."))
	}
	name := field.Ident[0]
	if _, ok := allowed[name]; !ok {
		return promptError("unknown_variable", "unknown template variable ."+name)
	}
	if onVariable != nil {
		onVariable(name)
	}
	return nil
}

func promptError(reason, message string) *platform.Error {
	err := platform.Invalid("system_prompt", message)
	err.Details["reason"] = reason
	return err
}
